<script setup>
import {computed,reactive,ref,onMounted,onUnmounted,watch} from 'vue'
import {data as articles} from '../../data/articles.data'
import {contentConfig as c} from '../../../../content.config'
import {filterArticles,queryFilters,filterQuery} from '../content-utils.mjs'
import ArticleCard from './ArticleCard.vue'
const filters=reactive(queryFilters(''));const expanded=ref(false);const searchInput=ref(null);let ready=false
function shortcut(e){if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)){e.preventDefault();searchInput.value?.focus()}}
const fields=[{key:'type',label:'内容类型',options:Object.entries(c.types).map(([value,label])=>({value,label}))},{key:'kind',label:'文章性质',options:Object.entries(c.kinds).map(([value,label])=>({value,label}))},{key:'industry',label:'适用行业',options:c.industries.map(i=>({value:i.name,label:i.name}))},{key:'tools',label:'工具 / 平台',options:c.tools.map(v=>({value:v,label:v}))},{key:'difficulty',label:'上手难度',options:c.difficulties.map(v=>({value:v,label:v}))},{key:'cost',label:'使用花费',options:c.costs.map(v=>({value:v,label:v}))}]
const results=computed(()=>filterArticles(articles,filters));const activeCount=computed(()=>Object.values(filters).filter(Boolean).length)
function restore(){Object.assign(filters,queryFilters(location.search))}
onMounted(()=>{restore();ready=true;addEventListener('popstate',restore);addEventListener('keydown',shortcut)})
onUnmounted(()=>{removeEventListener('popstate',restore);removeEventListener('keydown',shortcut)})
watch(filters,()=>{if(!ready)return;const q=filterQuery(filters);history.replaceState(history.state,'',location.pathname+(q?'?'+q:'')+location.hash)})
function reset(){Object.assign(filters,queryFilters(''))}
</script>
<template><div class="catalog-layout"><aside class="filter-panel" :class="{expanded}"><div class="filter-heading"><strong>缩小查找范围</strong><button class="mobile-filter-toggle" @click="expanded=!expanded" :aria-expanded="expanded">{{expanded?'收起条件':'展开条件'}}</button><button @click="reset">重置<span v-if="activeCount"> ({{activeCount}})</span></button></div><fieldset v-for="field in fields" :key="field.key"><legend>{{field.label}}</legend><div class="filter-options"><button :aria-pressed="!filters[field.key]" @click="filters[field.key]=''">全部</button><button v-for="option in field.options" :key="option.value" :aria-pressed="filters[field.key]===option.value" @click="filters[field.key]=filters[field.key]===option.value?'':option.value">{{option.label}}</button></div></fieldset><div class="filter-checks"><label><input type="checkbox" v-model="filters.recent">只看 30 天内更新</label><label><input type="checkbox" v-model="filters.original">只看自研资源</label><label><input type="checkbox" v-model="filters.archived">包含停止维护的内容</label></div></aside><section class="catalog-results"><div class="catalog-heading"><p class="eyebrow">找到能帮上忙的那一个</p><h1>总览筛选</h1><p>按行业、工具和花费，找到适合当前任务的方法。</p></div><label class="catalog-search"><span aria-hidden="true">⌕</span><input ref="searchInput" type="search" v-model="filters.q" placeholder="搜索任务、工具或关键词…" aria-label="搜索任务、工具或关键词"><kbd>/</kbd></label><div class="result-summary" aria-live="polite"><span>找到 <strong>{{results.length}}</strong> 篇内容 <span class="muted">/ 共 {{articles.length}} 篇</span></span><span>按最近更新排序</span></div><div class="article-grid"><ArticleCard v-for="article in results" :key="article.url" :article="article" /></div><div v-if="!results.length" class="empty-state"><span>⌕</span><h2>暂时没有匹配的内容</h2><p>试着减少一个筛选条件，或换一个任务关键词。</p><button class="primary-button" @click="reset">清空筛选</button></div></section></div></template>
